import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 1
            if i * i != n:
                count += 1
        i += 1
    return count

def check_solution(a, b, n):
    # 1. Check that a is the smallest prime factor (d2=a)
    if a < 2 or a != 2 and a not in [3, 5]: # Safety check for small a
        return False

    divisors = get_divisors(n)

    if len(divisors) < 5:
        return False

    d2 = divisors[1]
    d3 = divisors[2]
    d5 = divisors[4]

    is_valid = (d2 == a) and (d3 == b) and (d5 == a * b)

    if is_valid:
        return tau(n)
    return None

# --- Systematic Search ---
results = set()
primes = [2, 3, 5, 7] # Limit search space for initial findings

# Iterate over small primes a
for a in primes:
    # Iterate over potential third divisor b > a
    # We limit b to keep calculation feasible for small cases
    for b in range(a + 1, 20):
        # Necessary condition: c = ab, so n = ab(1+a+b)
        n = a * b * (1 + a + b)

        # Check constraint: a must be the smallest prime factor of n
        # We check this by seeing if any prime < a divides n.
        is_a_smallest_prime = True
        for p_test in range(2, a):
            if n % p_test == 0:
                is_a_smallest_prime = False
                break

        if not is_a_smallest_prime:
            continue

        # Check constraints d2=a, d3=b, d5=ab
        result_tau = check_solution(a, b, n)

        if result_tau is not None:
            results.add(result_tau)
            print(f"Found solution: a={a}, b={b}, n={n}, tau(n)={result_tau}")

print(f"All found tau values: {results}")
